// ArduPilot parameter documentation (generated by tools/gen-param-meta.mjs).
import type { VehicleClass } from './modes';

export interface ParamMeta {
  n?: string;                       // display name
  d?: string;                       // description
  u?: string;                       // units
  r?: [number, number];             // range
  i?: number;                       // increment
  v?: Record<string, string>;       // enum values
  b?: Record<string, string>;       // bitmask bits
  rb?: 1;                           // reboot required
  ro?: 1;                           // read-only
  adv?: 1;                          // advanced user level
}

interface MetaFile { params: Record<string, ParamMeta>; sources?: string[] }

const cache = new Map<VehicleClass, Promise<Record<string, ParamMeta>>>();

export function loadParamMeta(cls: VehicleClass): Promise<Record<string, ParamMeta>> {
  const key: VehicleClass = cls === 'unknown' ? 'copter' : cls;
  let p = cache.get(key);
  if (!p) {
    p = fetch(`${import.meta.env.BASE_URL}param-meta/${key}.json`)
      .then((r) => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() as Promise<MetaFile>; })
      .then((f) => f.params)
      .catch((e) => { cache.delete(key); console.warn('param metadata unavailable', e); return {}; });
    cache.set(key, p);
  }
  return p;
}

export function lookupMeta(meta: Record<string, ParamMeta>, name: string): ParamMeta | undefined {
  return meta[name];
}

/** "km/h" style units as ArduPilot writes them, with a few prettier symbols. */
export function prettyUnit(u?: string): string {
  if (!u) return '';
  const map: Record<string, string> = { 'deg/s': '°/s', deg: '°', degC: '°C', 'cdeg': 'c°', 'cdeg/s': 'c°/s', 'deg/s/s': '°/s²', 'm/s/s': 'm/s²', 'cm/s/s': 'cm/s²', 'centi-degrees': 'c°' };
  return map[u] ?? u;
}
